-- PostgreSQL: one atomic statement. Requires an existing users.id = 1.
-- All profile details, organizations, and accomplishments are fictional.
-- Each execution creates a new resume; IDs are generated by the database.
WITH
content AS (
    SELECT $resume_data$
[
{"label": "Header", "type": "header", "showHeading": false, "subsections": [{"label": "Jane Doe", "fields": [{"label": "Name", "value": [{"type": "paragraph", "label": "Name", "children": [{"text": "JANE DOE", "fontSizeOffset": 22, "lineHeightOffset": 0, "bold": true, "color": "#153E46"}]}]}, {"label": "Title", "value": [{"type": "paragraph", "label": "Title", "children": [{"text": "PRODUCT DESIGNER", "fontSizeOffset": 2, "lineHeightOffset": 0, "bold": true, "color": "#477078"}]}]}, {"label": "Contact", "value": [{"type": "paragraph", "label": "Contact", "children": [{"text": "Portland, OR  |  (503) 555-0142  |  jane.doe@example.com", "fontSizeOffset": -1, "lineHeightOffset": 0, "color": "#52616B"}]}]}, {"label": "Website", "value": [{"type": "paragraph", "label": "Website", "children": [{"text": "Portfolio: janedoe.example.com", "fontSizeOffset": -1, "lineHeightOffset": 0, "color": "#52616B"}]}]}]}]},
{"label": "Profile", "type": "summary", "showHeading": true, "subsections": [{"label": "Professional profile", "fields": [{"label": "Summary", "value": [{"type": "paragraph", "label": "Summary", "children": [{"text": "Product designer with 6 years of experience turning complex workflows into clear, accessible digital experiences. Combines user research, interaction design, and close engineering collaboration to deliver thoughtful products with measurable results.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "Experience", "type": "workHistory", "showHeading": true, "subsections": [{"label": "Northstar Studio", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Senior Product Designer", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Northstar Studio  |  Portland, OR  |  Jan 2023 - Present", "fontSizeOffset": -1, "lineHeightOffset": 0, "color": "#52616B"}]}]}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Redesigned onboarding for a B2B analytics platform, increasing activation by 24% and reducing time to first insight by 35%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Built a reusable design system with 40+ components, cutting design-to-development handoff time by 30%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Led interviews and usability studies with 45 customers to shape quarterly product priorities.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}, {"label": "Juniper Digital", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Product Designer", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Juniper Digital  |  Remote  |  Jun 2020 - Dec 2022", "fontSizeOffset": -1, "lineHeightOffset": 0, "color": "#52616B"}]}]}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Designed responsive checkout and account experiences that improved purchase completion by 18%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Partnered with engineers to resolve accessibility issues across 12 core screens.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Turned research findings into prototypes and specifications for a team of 8 engineers.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}]},
{"label": "Selected Project", "type": "projects", "showHeading": true, "subsections": [{"label": "Wayfinder", "fields": [{"label": "Project Title", "value": [{"type": "paragraph", "label": "Project Title", "children": [{"text": "Wayfinder - Community Resource Finder", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Dates", "value": [{"type": "paragraph", "label": "Dates", "children": [{"text": "Volunteer design project  |  2025", "fontSizeOffset": -1, "lineHeightOffset": 0, "color": "#52616B"}]}]}, {"label": "Description", "value": [{"type": "paragraph", "label": "Description", "children": [{"text": "Designed a mobile-first directory that helps residents find local food, housing, and career resources. Simplified navigation and validated the prototype through 10 moderated usability sessions.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "Skills", "type": "skills", "showHeading": true, "subsections": [{"label": "Core skills", "fields": [{"label": "Design", "value": [{"type": "paragraph", "label": "Design", "children": [{"text": "Design: Interaction design, visual design, prototyping, responsive layouts", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Research", "value": [{"type": "paragraph", "label": "Research", "children": [{"text": "Research: User interviews, usability testing, journey mapping, accessibility", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}, {"label": "Tools", "value": [{"type": "paragraph", "label": "Tools", "children": [{"text": "Tools: Figma, FigJam, HTML/CSS, design systems, developer handoff", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "Education", "type": "education", "showHeading": true, "subsections": [{"label": "Cascadia College", "fields": [{"label": "Degree", "value": [{"type": "paragraph", "label": "Degree", "children": [{"text": "B.A. in Communication Design", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "School", "value": [{"type": "paragraph", "label": "School", "children": [{"text": "Cascadia College  |  Portland, OR  |  2016 - 2020", "fontSizeOffset": -1, "lineHeightOffset": 0, "color": "#52616B"}]}]}]}]}
]
$resume_data$::jsonb AS sections
),
new_resume AS (
    INSERT INTO resumes (user_id, title, styling, layout, created_at, updated_at)
    VALUES (
        1,
        'Jane Doe - Modern Teal',
        '{"display":"flex","fontFamily":"Arial, Helvetica, sans-serif","fontSize":"9.5px","lineHeight":1.4,"color":"#24343D","backgroundColor":"#FFFFFF"}'::json,
        '{"padding":{"top":"2.5rem","right":"3rem","bottom":"2.5rem","left":"3rem"},"gap":{"horizontal":"1rem","vertical":"0.45rem","subsection":"0.8rem","field":"0.18rem"}}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    )
    RETURNING id, title
),
new_column AS (
    INSERT INTO columns (resume_id, position, styling, layout, created_at, updated_at)
    SELECT id, 0, '{}'::json,
        '{"width":{"auto":true,"value":"100%"},"padding":{"top":"0rem","right":"0rem","bottom":"0rem","left":"0rem"}}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_resume
    RETURNING id
),
section_data AS (
    SELECT (s.ordinality - 1)::integer AS position, s.item
    FROM content
    CROSS JOIN LATERAL jsonb_array_elements(content.sections)
        WITH ORDINALITY AS s(item, ordinality)
),
new_sections AS (
    INSERT INTO sections (
        column_id, label, type, value, show_heading, position,
        styling, layout, created_at, updated_at
    )
    SELECT c.id, s.item->>'label', s.item->>'type',
        jsonb_build_array(jsonb_build_object(
            'type', 'heading', 'label', s.item->>'label',
            'children', jsonb_build_array(jsonb_build_object(
                'text', upper(s.item->>'label'), 'bold', true,
                'fontSizeOffset', 0, 'lineHeightOffset', 0, 'color', '#26717A'
            ))
        ))::json,
        (s.item->>'showHeading')::boolean, s.position,
        '{}'::json,
        '{"display":"grid","grid":{"columns":1},"padding":{"top":"0rem","bottom":"0rem"}}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM section_data s CROSS JOIN new_column c
    RETURNING id, position
),
subsection_data AS (
    SELECT s.id AS section_id, (sub.ordinality - 1)::integer AS position, sub.item
    FROM new_sections s
    JOIN section_data d ON d.position = s.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'subsections')
        WITH ORDINALITY AS sub(item, ordinality)
),
new_subsections AS (
    INSERT INTO subsections (
        section_id, label, type, position, styling, layout, created_at, updated_at
    )
    SELECT d.section_id, d.item->>'label', s.item->>'type', d.position,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, '{}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM subsection_data d
    JOIN new_sections n ON n.id = d.section_id
    JOIN section_data s ON s.position = n.position
    RETURNING id, section_id, position
),
new_fields AS (
    INSERT INTO fields (
        subsection_id, label, value, position, styling, layout, created_at, updated_at
    )
    SELECT sub.id, f.item->>'label', (f.item->'value')::json,
        (f.ordinality - 1)::integer,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, '{}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_subsections sub
    JOIN subsection_data d ON d.section_id = sub.section_id AND d.position = sub.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'fields')
        WITH ORDINALITY AS f(item, ordinality)
    RETURNING id
)
SELECT id AS resume_id, title, (SELECT count(*) FROM new_fields) AS fields_created
FROM new_resume;
